-- ---------------------------------------------------------------------------
-- Onim — admin panel schema (migration 016)
--
-- The site says what it is, and the footer says where everything is.
--
-- Two things drifted once the site stopped being only a calculator library:
--
--  1. The pages. About, privacy, terms, disclaimer, contact and the FAQ were
--     written when calculators were the whole site, and they were between 1,200
--     and 4,100 characters long — enough for the old shape of the site, not
--     enough for a library of 4,060 tools in fifteen sections. Three pages a
--     reader is entitled to find did not exist at all: the cookie policy, the AI
--     policy, and a plain account of what the site holds and how to remove it.
--
--  2. The footer. It listed four calculator categories, three company links and
--     four resources — and "Discover Onim", which has 404'd since the rebuild. A
--     visitor at the bottom of a page could not reach a single tool section, and
--     the policies were a line of small print rather than pages.
--
-- This migration rewrites those nine pages from the copy in data/pages/*.json
-- (the same copy a fresh install gets) and rebuilds the footer around them. It
-- matches pages by slug, so a site that already has them is updated rather than
-- duplicated, and it does not touch pages the owner created.
--
-- templates/partials/footer.php does not wait for this file: it renders the tool
-- sections, the policies and the corrected counts on a database that has not run
-- it yet. This migration is what puts the same links in front of the owner in
-- Header & footer, where they can be renamed, moved or deleted.
-- ---------------------------------------------------------------------------

SET NAMES utf8mb4;

-- The nine pages, written out in full. ON DUPLICATE KEY UPDATE means a re-run
-- refreshes the copy instead of failing on the unique slug index; author_id and
-- created_at are left alone.
INSERT INTO `pages`
    (`slug`, `title`, `excerpt`, `content`, `template`, `status`,
     `meta_title`, `meta_description`, `canonical_url`, `noindex`,
     `show_in_header`, `show_in_footer`)
VALUES
  ('about', 'About Onim', 'A free library of 4,041 calculators and 19 file tools across fifteen sections — who does what, how each answer is checked, and what the site does with what you type.', '<p><strong>Onim</strong> is a free collection of 4,041 calculators and 19 browser-based file tools — 4,060 tools in all — organised into fifteen sections. Calculators are one section of this site, not the whole of it: the same catalogue that holds the Math, Finance and Physics calculators also holds the Audio, Video, Image, PDF, Developer, Converter, Security, Gaming, Compressor, Productivity, Design &amp; CSS, Text &amp; Writing, Art &amp; Color and Social &amp; Community tools. You pick a section, you pick a tool, and the page shows the formula or the method that produced the answer. No account, no paywall, no "unlock the result" step.</p>\n<figure class="about-figure">\n<img src="/uploads/about/workspace.jpg" width="1280" height="715" loading="lazy" decoding="async" alt="The Onim desk: two monitors showing the tool catalogue and a calculator, with a notebook of worked formulas open in front.">\n<figcaption>Where the pages are built and checked — the catalogue on the left, a calculator under test on the right.</figcaption>\n</figure>\n<h2>One site, fifteen sections</h2>\n<p>The site is not a calculator website with a tools page bolted on, and it is not a file-tools website either. It is a library in which calculators are one category. The fifteen sections are:</p>\n<ul>\n<li><strong>Calculators</strong> — 4,041 pages across Biology, Chemistry, Construction, Conversion, Ecology, Everyday life, Finance, Food, Health, Math, Physics, Sports, Statistics and Other. Every page has inputs, a result and the equation it used.</li>\n<li><strong>Audio Tools, Video Tools, Image Tools, PDF Tools, Developer Tools, Converters, Security Tools, Gaming Tools, Compressors, Productivity Tools, Design &amp; CSS Tools, Text &amp; Writing Tools, Art &amp; Color Tools, Social &amp; Community Tools and Fun &amp; Random Tools</strong> — 19 working tools that take a file, a link or a snippet of text and give you back something usable. They run in the browser: the file you hand over is never uploaded.</li>\n</ul>\n<p>Every section has the same furniture, so moving from a loan calculator to a video frame grabber does not feel like changing sites: a searchable list of that section''s tools, a "browse all" index, and a card for each tool that states what it does in one sentence.</p>\n<h2>Why the calculator pages are built the way they are</h2>\n<p>A calculator that only prints a number is a black box, and a black box is not much use when the number matters. Each calculator is described by the relationships between its inputs. Those equations are what the page runs on — once on the server while the page is drawn, and again in your browser the moment you press Calculate, so the two can be compared. Where a problem needs more than arithmetic (a table lookup, an iterative solve, a piecewise rule, a tax band), that logic is written out step by step instead of being hidden.</p>\n<p>Every calculator page therefore carries the same parts: the formula with its variables defined, a worked example with real numbers, the assumptions the answer rests on, a table of neighbouring results, a short article on what the result means and where people get it wrong, and the questions readers actually ask about it.</p>\n<h2>How the tools are built</h2>\n<p>The file tools are written to do one job properly rather than many jobs approximately. An image compressor that changes the dimensions is not a compressor, and a converter that silently re-encodes your audio is worse than one that refuses. Where a tool cannot do something exactly — a PDF that will not extract as editable text, a colour profile that has no browser-side equivalent — the page says so before you run it, in the same place you would have found the "Start" button.</p>\n<p>Everything that can stay on your device does. Files are read with the browser''s own APIs, processed in the page and handed back for download. Nothing is posted to a server, and nothing is kept after you close the tab.</p>\n<h2>How the answers are checked</h2>\n<p>Each calculator is tested against worked examples whose results are stated independently of the code: the answer is computed by hand or taken from an authoritative source, then the page has to reproduce it. A calculator that disagrees with its worked example is a bug, and it is fixed rather than annotated. Every field is tested with numbers below and above its sensible range, letters are refused with a message under the field rather than a silent zero, and every result is checked for its unit and rounded to no more than three decimals.</p>\n<p>File tools are tested on files with known properties — a 1200-pixel image that has to come back 1200 pixels wide, a PDF whose page count must not change, an audio file whose duration is the same after conversion. The tests run on every release, on the live site as well as locally.</p>\n<h2>Who does what</h2>\n<p>Onim is written and maintained by a small independent team, and every page has exactly three jobs behind it: someone writes it and checks that the prose matches the formula, someone builds the solver or the tool and keeps it running, and someone checks the subject against a published source before it goes live. The same person often does two of them, which is why a calculator that is wrong is usually fixed the same week it is reported.</p>\n<div class="team-grid">\n<article class="team-card">\n<img src="/uploads/about/team-editorial.jpg" width="640" height="736" loading="lazy" decoding="async" alt="Illustrative portrait: the editorial desk, where calculator articles are written and checked.">\n<div class="team-card-body">\n<h3 class="team-name">Editorial</h3>\n<p class="team-role">Calculators and articles</p>\n<p class="team-bio">Writes the explanation behind every calculator page: the formula with its variables defined, the worked example, the assumptions the answer rests on, and the part that says where people go wrong. Reads each draft against the equation rather than against the previous draft.</p>\n<p class="team-detail">The test a page has to pass: it should be able to explain its own answer to someone who has put the calculator away.</p>\n</div>\n</article>\n<article class="team-card">\n<img src="/uploads/about/team-engineering.jpg" width="640" height="736" loading="lazy" decoding="async" alt="Illustrative portrait: the engineering desk, where the file tools and the site itself are built and tested.">\n<div class="team-card-body">\n<h3 class="team-name">Engineering</h3>\n<p class="team-role">File tools and platform</p>\n<p class="team-bio">Builds the browser-side tools, the calculator solver, the search and the pages themselves. The rule applied to a file tool is that it does the one job it claims and refuses rather than guesses — a converter that silently re-encodes is a bug, not a feature.</p>\n<p class="team-detail">Reads every bug report that arrives through the contact form, usually before anyone else sees it.</p>\n</div>\n</article>\n<article class="team-card">\n<img src="/uploads/about/team-review.jpg" width="640" height="736" loading="lazy" decoding="async" alt="Illustrative portrait: the review desk, where health and science results are checked against primary sources.">\n<div class="team-card-body">\n<h3 class="team-name">Review</h3>\n<p class="team-role">Health, biology and chemistry</p>\n<p class="team-bio">Checks the results that people act on against primary sources and clinical convention, and signs off the numbers that go into the worked examples. Where a formula has more than one convention — a calorie, a tonne, a definition of normal — the page has to say which one it uses.</p>\n<p class="team-detail">The rule for a result someone might act on: if a careful reader could misread it, it is worded wrongly.</p>\n</div>\n</article>\n</div>\n<p class="team-note">The three portraits and the workspace photograph on this page are illustrative images made for Onim, not photographs of named individuals. They are labelled as such, and the <a href="/ai-policy">AI policy</a> says how images on the site are produced. Nothing on this site publishes a testimonial, a reviewer or a user that does not exist.</p>\n<h2>How we work, and how you can tell</h2>\n<p>Every page states when it was last updated, and the calculators are revised when a formula, a unit convention or a tax rule changes. Corrections are made to the page, not appended in a footnote, and a page that disagrees with its own worked example is treated as broken until it is fixed.</p>\n<p>If a page is wrong, the fastest way to have it corrected is to tell us what you entered, what you got and what you expected — the <a href="/contact">contact page</a> takes all three. Reviews on calculator pages come from readers and are published under the name the reader chose; none of them is written by us.</p>\n<h2>What happens to what you type</h2>\n<p>Calculations run in your browser and on this server while the page is being drawn. We do not store your inputs into a calculator, we do not build profiles from them, and we do not sell data to anyone. Uploaded files are read in your browser and never leave it. The only information we keep is what you deliberately send — a message through the contact form, a name attached to a review, or a like on a page — and each of those is described in the <a href="/privacy">privacy policy</a>, which also says how to have it removed.</p>\n<h2>How the site is paid for</h2>\n<p>Onim is free to use and costs money to run. It is funded by advertising: a small number of clearly marked placements, never inside a result and never between you and an answer. Advertisers do not see the values you enter, cannot influence a result, and get no access to the calculators themselves. If advertising is switched off on this deployment, nothing else about the site changes.</p>\n<h2>Why we write policies in plain language</h2>\n<p>A site that asks you to trust its arithmetic should be equally clear about what it does with your data, what it will not do with your files, and where it stops being an authority. That is why <a href="/privacy">Privacy</a>, <a href="/cookies">Cookies</a>, <a href="/ai-policy">AI policy</a>, <a href="/terms">Terms</a> and <a href="/disclaimer">Disclaimer</a> are written as pages a reader can actually finish, rather than as boilerplate. They describe this site as it is: a free tool library, run by three people, funded by ads, storing almost nothing.</p>\n<h2>How this page was made</h2>\n<p>Some drafting and code review on this site is AI-assisted; the formulas, worked examples and review passes are written and checked by a person, and the <a href="/ai-policy">AI policy</a> says exactly which parts that applies to and which it does not. The images on this page were generated for Onim rather than licensed from a stock library, which is why they are labelled as illustrative rather than presented as photographs of the team.</p>\n<h2>Getting in touch</h2>\n<p>Bug reports, corrections and requests all go to the same place. If a result looks wrong, the calculator name, the values you entered and the answer you expected is usually enough to reproduce it. Requests for a calculator or a file format are read, and a good share of what is on the site today started as one of those messages.</p>', 'default', 'published', 'About Onim — a tool library, checked page by page', 'Who builds Onim, how the 4,041 calculators and 19 file tools are written and checked, who does what on the team, and what the site does with your data.', '', 0, 0, 1),
  ('privacy', 'Privacy policy', 'What this site collects, what it deliberately does not, how long anything is kept, and how to have it removed.', '<p>This policy explains what Onim does with data. It covers the calculator pages, the file tools, the blog, the reviews and likes, and the contact form. It is written to be read in one sitting, and it describes the site as it actually runs rather than a template of what a site might do.</p>\n<p><strong>In one paragraph:</strong> we do not have accounts, we do not store what you type into a calculator, files you open in a tool never leave your browser, and the only things we keep are the ones you deliberately send us — a contact message, a review, a like — plus ordinary web-server log lines. We do not sell data, we do not build advertising profiles, and we do not run third-party tracking scripts.</p>\n<h2>Who is responsible</h2>\n<p>Onim is a free tool library published and operated by the small independent team described on the <a href="/about">About page</a>. That team is the data controller for the small amount of personal data described here. The address for every data question — access, correction, deletion, objection — is the <a href="/contact">contact form</a>, and messages sent through it reach the people who can act on them.</p>\n<p>If a request concerns a message you sent us, a review you posted or a like you registered, say so in the subject line; it is routed to the same inbox either way, but the label saves a round trip.</p>\n<h2>What this site does not collect</h2>\n<p>It is easier to start with the absences, because they are the part that matters most:</p>\n<ul>\n<li><strong>No accounts.</strong> There is no sign-up, no login and no profile for visitors. The public site has no session cookie and no user table.</li>\n<li><strong>No storage of calculator inputs.</strong> The values you type into a calculator are used to compute the result in front of you. They are held in the page while you are on it and they are gone when you leave or reload. They are not written to a database and they are not attached to you.</li>\n<li><strong>No uploads.</strong> The file tools read the file you choose with the browser''s own file APIs and process it inside the page. The file is never posted to a server; there is no upload endpoint for it to reach.</li>\n<li><strong>No advertising profiles.</strong> We do not run third-party tracking pixels, we do not build behavioural segments, and we do not pass anything you do here to a data broker.</li>\n<li><strong>No cross-site tracking.</strong> Nothing on Onim follows you to another website, and nothing from another website is used to recognise you here.</li>\n</ul>\n<h2>What we do collect, and why</h2>\n<h3>Server logs</h3>\n<p>Like every web server, ours records each request: the IP address that made it, the date and time, the URL requested, the HTTP status and the browser''s user-agent string. These lines exist to keep the site running — diagnosing errors, measuring load and spotting abuse — and they are kept for a short period (normally no more than thirty days) before being rotated out. They are not combined with anything else to identify a person, and they are not used for marketing.</p>\n<h3>Page counters</h3>\n<p>To know which pages are worth improving, the site keeps a daily counter per page: the page path, the date, and a number. There is no visitor identifier in that counter, no cookie, and no way to work backwards from it to a person. It answers "was this page read this week?", not "who read it".</p>\n<h3>The contact form</h3>\n<p>When you send a message we store the name, email address, phone number (if you fill it in), subject and message you submit, together with the IP address the message came from and the time it arrived. The IP address is used for one thing: rate limiting. A visitor can send five messages an hour, after which the form asks them to wait; that rule is what keeps the form usable for everyone else.</p>\n<p>The message is stored in the site''s database first and a notification email is sent to the team second, so a mail failure never loses your message. Messages are kept until the question is settled and for a short period afterwards in case of a follow-up, then deleted. Nothing in a contact message is ever used for marketing, added to a mailing list or shared with a third party.</p>\n<h3>Reviews and likes</h3>\n<p>Calculator pages let readers leave a review and register a like. A review stores the display name you choose, an optional title, the text of the review, the rating, the time it was posted and a shortened browser user-agent string — the last two so that spam and duplicate submissions can be recognised. Reviews are public: whatever you type in the name and text fields will be visible to anyone who opens the page. We do not ask for an email address on a review, and we do not publish the IP address or the cookie token with it.</p>\n<p>A like stores only a count against the page. To stop one browser from voting repeatedly, the site keeps a small anonymous token (see <a href="/cookies">Cookies</a>) and a list of pages that token has already liked. That list is what "you have already liked this calculator" is read from. It contains no name, no email address and no browsing history outside this site.</p>\n<h3>Messages sent to the team about the site itself</h3>\n<p>If you email the team directly rather than using the form — for example about licensing, a legal request or a press enquiry — your message sits in that mailbox. It is kept for as long as the correspondence needs, and deleted when it no longer does.</p>\n<h2>Files you open in a tool</h2>\n<p>The Audio, Video, Image, PDF, Developer, Converter, Security, Compressor, Productivity and Text tools all run in the browser. The file you select is read into the page''s memory, processed there, and offered back to you as a download. It is not transmitted, not cached on the server and not retained after you close or reload the tab. If a tool cannot do a job without sending the file somewhere, the page says so before you start, and no shipped tool currently needs to.</p>\n<h2>Cookies and local storage</h2>\n<p>The public site sets one cookie, and only when you use a feature that needs it: an anonymous token that remembers which pages you have already liked. It carries no personal information, and clearing it merely resets those counters. There are no advertising or analytics cookies on the site as shipped. The full list, with names and lifetimes, is on the <a href="/cookies">cookie policy</a>.</p>\n<h2>Analytics</h2>\n<p>As shipped, Onim runs no analytics script at all: page counts come from the server''s own counter. If the operator of a deployment turns on a third-party analytics provider — Google Analytics 4, Plausible or Umami, chosen in the admin panel — then that provider''s script loads on every page and its own privacy terms apply. This site''s configuration is visible on the cookie policy page, which states which provider, if any, is active.</p>\n<h2>Advertising</h2>\n<p>The site is free because it is funded by advertising, but advertising here is deliberately small: a handful of clearly marked placements, never inside a result and never between you and an answer. We do not put your calculator inputs, your files or your reviews into an ad request. Where a placement is filled by a third-party network that uses cookies for frequency capping or measurement, that network''s own policy governs its cookies, and the cookie policy lists the categories. On the deployment as shipped, no network script is loaded.</p>\n<h2>Who else sees data</h2>\n<p>Only the providers needed to run the site see anything at all, and each sees the minimum:</p>\n<ul>\n<li><strong>The hosting provider</strong> serves the pages and therefore sees the same request information your browser sends to any website (IP address, URL, user-agent).</li>\n<li><strong>The outbound mail provider</strong> carries the notification email for a contact message, which contains the message you wrote.</li>\n<li><strong>An analytics provider, if one is switched on</strong>, receives page views under its own terms, as described above.</li>\n</ul>\n<p>We do not sell personal data. We do not share it with advertisers, data brokers or marketing platforms, and we do not transfer it for anyone else''s purposes.</p>\n<h2>How long things are kept</h2>\n<table>\n<caption>Retention at a glance</caption>\n<thead><tr><th>What</th><th>How long</th></tr></thead>\n<tbody>\n<tr><td>Server log lines</td><td>A short period, normally no more than 30 days</td></tr>\n<tr><td>Daily page counters</td><td>Indefinitely, as aggregate numbers only</td></tr>\n<tr><td>Contact messages</td><td>Until the question is settled, plus a short follow-up window; deleted on request</td></tr>\n<tr><td>Reviews</td><td>Until you ask for removal, or until the page they belong to is retired</td></tr>\n<tr><td>Like tokens and like lists</td><td>Up to 12 months, or until the cookie is cleared</td></tr>\n<tr><td>Calculator inputs</td><td>Not stored at all</td></tr>\n<tr><td>Files opened in a tool</td><td>Not transmitted; gone when the tab closes</td></tr>\n</tbody>\n</table>\n<h2>Your rights, and how to use them</h2>\n<p>If you are in the European Economic Area, the United Kingdom, Switzerland or another jurisdiction with a comparable framework, you have the right to ask for a copy of the personal data we hold about you, to have it corrected, to have it deleted, to restrict or object to its processing, and to receive it in a portable format. If you are in California, you have the right to know what is collected, to delete it, to correct it, and not to be discriminated against for exercising those rights.</p>\n<p>In practice, the list above is short and concrete: contact messages, reviews and like tokens. Write through the <a href="/contact">contact form</a> and say what you want — a copy, a correction, a deletion or an objection — and it will be handled by a person. We answer within 30 days and usually much sooner. There is a worked-out description of each route on the <a href="/your-data">your data and your choices</a> page.</p>\n<p>Where processing needs a legal basis: server logs and abuse prevention rest on the legitimate interest of keeping the service available and safe; a contact message is handled because you asked us to answer it; a review or a like is published because you chose to post it. Nothing here depends on consent obtained through a pre-ticked box, because there is no such box.</p>\n<h2>Children</h2>\n<p>Onim is a general-purpose tool library, not a service aimed at children. We do not knowingly collect personal data from anyone under 13, and the site asks for no personal details to use a calculator or a file tool. If a message or review appears to come from a child under 13, it is removed on request from a parent or guardian.</p>\n<h2>Security</h2>\n<p>The public pages are served over HTTPS. The admin area — which is not part of the public site and holds no visitor data beyond what is described above — requires a login and a session cookie. Form submissions carry a per-visitor token to prevent cross-site request forgery, and contact messages are rate-limited by IP. No system is perfect; if you find a problem, tell us through the contact form and it will be treated as urgent.</p>\n<h2>International transfers and hosting</h2>\n<p>The site is served from a hosting provider''s data centre, which may be outside your country. That is inherent in visiting any website: the request has to travel to wherever the server is. We do not add any further transfer of your data between countries.</p>\n<h2>Changes to this policy</h2>\n<p>When something here changes, the date at the top of the page changes with it, and the change is described rather than silently made. Material changes — a new data category, a new provider, a different retention period — are noted in the section they affect. The policy has been written to match the code: if you find a sentence here that the site does not do, that is a bug, and we would like to hear about it.</p>\n<h2>Related pages</h2>\n<p><a href="/cookies">Cookie policy</a> — every cookie and storage key, with names and lifetimes. <a href="/your-data">Your data and your choices</a> — how to request a copy or a deletion, step by step. <a href="/ai-policy">AI policy</a> — how AI tooling is and is not used on this site. <a href="/terms">Terms of use</a> and <a href="/disclaimer">Disclaimer</a> — the rules of use and the limits of the results.</p>', 'default', 'published', 'Privacy policy — what Onim keeps and what it never sees', 'The data this tool site collects, what it never stores, how long anything is kept, and how to request a copy, a correction or a deletion.', '', 0, 0, 1),
  ('cookies', 'Cookie policy', 'Every cookie and every storage key this site uses, with names, purposes and lifetimes — and what is deliberately absent.', '<p>This page lists every cookie and every piece of browser storage Onim uses, what each one is for, and how long it lasts. There are very few of them. There are no advertising cookies on the site as shipped, no third-party tracking scripts, and no consent wall, because there is nothing to consent to in order to use a calculator.</p>\n<h2>What a cookie is, in one paragraph</h2>\n<p>A cookie is a small text file a website asks your browser to keep on your device and to send back with each later request to that site. It cannot read other files, it cannot run a program, and it cannot see other websites'' cookies. Browsers also offer two other kinds of storage — <em>local storage</em> and <em>session storage</em> — which hold small values on your device without sending them to the server on every request. Onim uses one cookie and one local-storage key, both described below.</p>\n<h2>The cookie the public site sets</h2>\n<table>\n<caption>First-party cookies</caption>\n<thead><tr><th>Name</th><th>What it holds</th><th>Why</th><th>Lifetime</th></tr></thead>\n<tbody>\n<tr>\n<td><code>onim_vid</code></td>\n<td>A random 24-character hexadecimal token, for example <code>9f2c1a…</code>. It contains no name, email address or location.</td>\n<td>It is created the first time you like a calculator or post a review, and it is read afterwards only to stop the same browser from registering the same like twice. It is also what makes "you have already liked this calculator" possible.</td>\n<td>Up to 12 months, then it expires. Clearing site data resets it immediately.</td>\n</tr>\n</tbody>\n</table>\n<p><code>onim_vid</code> is a first-party cookie: it is set by this site for this site. It is marked <code>HttpOnly</code>, so page scripts cannot read it, and <code>SameSite=Lax</code>, so it is not sent when another website links you here from a form. It is not used for advertising, not used to build a profile, and not shared with anyone.</p>\n<h2>Local storage on your device</h2>\n<table>\n<caption>Browser storage</caption>\n<thead><tr><th>Key</th><th>What it holds</th><th>Why</th><th>Lifetime</th></tr></thead>\n<tbody>\n<tr>\n<td><code>omni_preferred</code></td>\n<td>The single value <code>yes</code> or <code>no</code>.</td>\n<td>Remembers whether you pressed "Add as preferred on Google" on this device, so the button shows the right state when you return. It never leaves your browser and is never sent to us.</td>\n<td>Until you clear site data, or press the button again.</td>\n</tr>\n</tbody>\n</table>\n<p>Local storage stays on your device. Unlike a cookie it is not attached to your requests, so the server never sees it.</p>\n<h2>The admin area''s session cookie</h2>\n<p>The site''s administration panel — a separate area at <code>/admin</code>, not part of the public site — uses one PHP session cookie called <code>onim_sid</code> to keep an editor signed in. It is set only after a successful login, it is <code>HttpOnly</code> and <code>SameSite=Lax</code>, and it is destroyed when the editor signs out. A visitor to any public page never receives it.</p>\n<h2>What is not here</h2>\n<ul>\n<li><strong>No analytics cookies on the site as shipped.</strong> Page counts come from the server''s own counter, not from a script in your browser.</li>\n<li><strong>No advertising cookies on the site as shipped.</strong> The ad placements in the page are empty until an operator fills them.</li>\n<li><strong>No social media pixels, no heat-mapping scripts, no A/B testing framework, no tag manager.</strong></li>\n<li><strong>No cookie banner</strong>, because the one cookie above is strictly functional: it exists only because you used a feature that requires it.</li>\n</ul>\n<h2>If the operator enables analytics</h2>\n<p>A deployment can switch on one analytics provider in the admin panel. When one is active, its script loads on every page and sets its own cookies under its own terms; this site does not merge that data with anything else. The providers that can be selected are:</p>\n<ul>\n<li><strong>Plausible</strong> — cookieless by design. It records page views without a persistent identifier.</li>\n<li><strong>Umami</strong> — cookieless by default, recording aggregate page views and referrers.</li>\n<li><strong>Google Analytics 4</strong> — sets first-party cookies (<code>_ga</code> and <code>_ga_*</code>, up to 13 months) and processes data under Google''s terms. If it is switched on here, those cookies appear in your browser and can be blocked or deleted in the usual way.</li>\n</ul>\n<p>The current state of this deployment is stated in the answer below, so you do not have to take a general statement on trust.</p>\n<h2>If the operator enables advertising</h2>\n<p>The site has ad placements in fixed positions — never inside a calculation, never between a question and its answer. When a placement is filled by a third-party network, that network may set cookies for frequency capping, fraud prevention and measurement, and may use them across the sites it serves. Those cookies are set by the network, not by Onim, and they fall under that network''s policy; the placement itself is labelled as advertising wherever it appears. As shipped, no network script is loaded and no such cookie is set.</p>\n<h2>Controlling cookies on your side</h2>\n<p>Every major browser lets you see, block and delete cookies and site data. Blocking <code>onim_vid</code> breaks nothing except the memory of which pages you have already liked — the site works normally without it. Blocking local storage likewise only affects the preferred-source button. If you never press a like button or post a review, no cookie is set on your device at all.</p>\n<p>Most browsers also offer a private or incognito window, which discards all of this when you close it. The file tools work there too, because they never needed a server in the first place.</p>\n<h2>The current configuration of this deployment</h2>\n<ul>\n<li><strong>Analytics:</strong> none — no third-party analytics script is loaded.</li>\n<li><strong>Advertising:</strong> no network tags are loaded; ad placements are empty.</li>\n<li><strong>Cookies set on a normal visit:</strong> none. <code>onim_vid</code> appears only after you like a calculator or post a review.</li>\n</ul>\n<h2>Questions</h2>\n<p>If something in your browser''s cookie list looks like it came from this site and is not described here, send the name through the <a href="/contact">contact form</a> and it will be traced and either explained or removed. The <a href="/privacy">privacy policy</a> covers the wider question of what the site does with data, and <a href="/your-data">your data and your choices</a> explains how to have anything removed.</p>', 'default', 'published', 'Cookie policy — the one cookie Onim sets, and when', 'Every cookie and storage key used on Onim, with names and lifetimes, plus what the site deliberately does not set and how to clear it.', '', 0, 0, 1),
  ('ai-policy', 'AI policy', 'Where AI tooling is used on this site, where it is not, and how an AI-assisted page is checked before it ships.', '<p>Some of the writing and code on Onim is drafted with the help of AI tools, and some is not. This page says which is which, how the two are kept apart, and what happens when an AI-assisted draft turns out to be wrong. It exists because "AI-generated" and "written by a person" are not useful answers on their own.</p>\n<h2>The short version</h2>\n<ul>\n<li><strong>No answer on this site is produced by an AI model at the moment you use it.</strong> Every calculator runs a formula that is written down and checked. Nothing you type is sent to a language model.</li>\n<li><strong>The explanations are human-reviewed.</strong> Articles, worked examples and the "what the result means" sections are drafted by the team and, where AI tooling was used for a first draft or a structural pass, the final text is read and corrected by a person who is named as responsible for the page.</li>\n<li><strong>Formulas are never left to a model.</strong> An equation, a unit conversion or a tax band is taken from a source, written by hand, and tested against a worked example with a known answer.</li>\n<li><strong>Your inputs and files are never used to train anything.</strong> Calculator values stay in your browser. Files opened in a tool never leave your device. No message you send is fed to a model.</li>\n</ul>\n<h2>Where AI tooling is used</h2>\n<h3>Drafting and editing</h3>\n<p>A first draft of an explanatory section may be produced with an AI writing tool from an outline supplied by the team — the formula, the variables, the assumptions and the reference the article has to agree with. The draft is then edited by a person, checked against the source, and rewritten where it is vague, padded or wrong. A page that has not been through that pass is not published.</p>\n<h3>Code review and testing</h3>\n<p>AI assistants are used as a second pair of eyes on code: to look for a missing edge case, an unhandled unit, a rounding error or a layout that breaks at a narrow width. They do not decide what a calculator does. Every formula, every unit table and every validation rule is human-specified, and the tests that decide whether a page ships are written by hand and run against known answers.</p>\n<h3>Images</h3>\n<p>The photographs on the <a href="/about">About page</a> were generated for this site rather than licensed from a stock library. They are illustrative portraits of the team, not photographs taken with a camera, and the About page says so. Diagram figures on calculator pages are drawn as SVG from the formula they illustrate, not generated from a prompt.</p>\n<h3>Translations and accessibility fixes</h3>\n<p>Short interface strings and alt-text may be drafted with assistance and checked by a person. Alt-text for a diagram is written from the diagram''s actual content, because a caption that describes the wrong chart is worse than no caption.</p>\n<h2>Where AI tooling is not used</h2>\n<ul>\n<li><strong>Calculation.</strong> The solver that computes a result is deterministic code. The same inputs give the same answer on every visit, and the formula is printed on the page so you can check it by hand.</li>\n<li><strong>Medical, financial and legal framing.</strong> The passages that tell you what a result does and does not mean are written or signed off by the person responsible for that subject area, not generated.</li>\n<li><strong>Decisions about you.</strong> There is no automated decision-making about visitors, no scoring, no profiling and no personalisation driven by a model.</li>\n<li><strong>Moderation of your messages.</strong> Contact messages and reviews are read by a person. Spam rules are plain, published rules (no links in reviews, a rate limit per address), not a model''s judgement.</li>\n</ul>\n<h2>How an AI-assisted page is checked before it ships</h2>\n<ol>\n<li><strong>The formula is fixed first.</strong> It comes from a textbook, a standard, a datasheet or a regulator''s published rule, and the source is named on the page.</li>\n<li><strong>The worked example is computed independently.</strong> By hand, in a spreadsheet or from the source''s own example — never by the code being tested.</li>\n<li><strong>Every field is exercised.</strong> Ordinary values, boundary values, a value that is out of range and a letter where a number belongs. A wrong entry gets a message under the field; it does not quietly produce a zero.</li>\n<li><strong>The prose is read against the formula.</strong> If the article says "halve the diameter and the area falls by four", someone checks that the equation actually does that.</li>\n<li><strong>The page is read on a phone.</strong> Long formulas and wide tables have a habit of being unreadable at 390 pixels wide, which is a correctness problem on a tool site.</li>\n<li><strong>A person signs off.</strong> The page carries the date it was last updated, and a correction goes into the page rather than into a footnote.</li>\n</ol>\n<h2>What happens when AI-assisted work is wrong</h2>\n<p>It gets fixed the same way any other error does: the page is corrected, the worked example is re-run, and if the mistake came from a repeated pattern — a unit table copied wrongly, a rounding rule applied in the wrong place — every page that shares the pattern is checked. A wrong result is a bug on this site, not a disclaimer. If you find one, the <a href="/contact">contact form</a> takes the calculator name, the values you entered and the answer you expected.</p>\n<h2>Copyright and sources</h2>\n<p>Text on this site is written for it. Formulas, unit definitions and regulatory thresholds are facts and are not owned by anyone; where a page leans on a specific source, the source is named. We do not reproduce long passages from other websites, and we do not use AI tooling to rewrite someone else''s article into a "new" one. If you believe a page reproduces your work, tell us and it will be checked and removed if the complaint is right.</p>\n<h2>What we will not do with AI</h2>\n<ul>\n<li>We will not put a generated answer in place of a calculation and present it as computed.</li>\n<li>We will not invent a quotation, a study, a reviewer or a user testimonial.</li>\n<li>We will not generate medical, legal or financial advice and dress it as a result of a formula.</li>\n<li>We will not use a model to make a decision about whether your message is spam and then refuse to show you why.</li>\n<li>We will not train anything on the values you enter or the files you open, because we do not receive them.</li>\n</ul>\n<h2>Keeping this page honest</h2>\n<p>If a page on this site looks machine-written in the bad sense — confident, vague, restating the heading, unable to say where a number comes from — that page is unfinished. Send the address through the <a href="/contact">contact form</a> and it will be rewritten. The <a href="/about">About page</a> describes who writes what, and the <a href="/privacy">privacy policy</a> describes what the site does with data.</p>', 'default', 'published', 'AI policy — where AI is used on Onim, and where it is not', 'How Onim uses AI tooling for drafting and code review, what is never left to a model, and how AI-assisted pages are checked before publishing.', '', 0, 0, 1),
  ('your-data', 'Your data and your choices', 'The complete list of what this site holds about you, and the exact steps to see it, correct it, export it or delete it.', '<p>This page is the practical half of the <a href="/privacy">privacy policy</a>: it lists the only personal data this site holds, and gives the exact steps to see it, correct it, export it or have it deleted. Every route ends in a person reading a message, not in a form that disappears.</p>\n<h2>What we hold about you — and what we do not</h2>\n<table>\n<caption>The complete list</caption>\n<thead><tr><th>Category</th><th>Held?</th><th>Where it comes from</th></tr></thead>\n<tbody>\n<tr><td>What you type into a calculator</td><td><strong>No</strong></td><td>Stays in the page; gone when you leave.</td></tr>\n<tr><td>Files you open in a tool</td><td><strong>No</strong></td><td>Processed in your browser; never transmitted.</td></tr>\n<tr><td>Browsing history across other sites</td><td><strong>No</strong></td><td>Nothing here can see it.</td></tr>\n<tr><td>An account, password or profile</td><td><strong>No</strong></td><td>There are no visitor accounts.</td></tr>\n<tr><td>Server log lines (IP, time, URL, browser)</td><td><strong>Yes</strong>, briefly</td><td>Written automatically by the web server; rotated within about 30 days.</td></tr>\n<tr><td>A contact message you send</td><td><strong>Yes</strong></td><td>Name, email, optional phone, subject, message, IP, time.</td></tr>\n<tr><td>A review you post</td><td><strong>Yes</strong>, publicly</td><td>Display name, optional title, text, rating, time, shortened user-agent.</td></tr>\n<tr><td>An anonymous like token</td><td><strong>Yes</strong></td><td>A random string in the <code>onim_vid</code> cookie, plus the pages it has liked.</td></tr>\n</tbody>\n</table>\n<p>If something you are looking for is not in that table, the site does not have it. That is not a rhetorical claim: the code is written so that calculator inputs never reach a database and files never reach the server, which is why the list is this short.</p>\n<h2>Get a copy of what we hold</h2>\n<p>Send a message through the <a href="/contact">contact form</a> with the subject <strong>Data request — copy</strong>. Include the email address you used when you wrote to us, and — if you posted a review — the display name and the page it is on. You will receive a plain-text summary of every record that matches: the message rows, the review rows and the like token if there is one. If nothing matches, we will say so explicitly rather than leaving you to guess.</p>\n<p>You do not need to give a reason. A copy takes nothing more than the details above, and it is answered within 30 days, usually within a few.</p>\n<h2>Correct something</h2>\n<p>A typo in a review, a wrong name, a message you sent from the wrong address: send the correction through the form with the subject <strong>Data request — correction</strong>, quoting the page and what should change. Reviews are edited in place; a corrected review keeps a note that it was corrected only if the change alters what it says about a result.</p>\n<h2>Delete something</h2>\n<p>Three different things can be deleted, and the route is the same for all of them:</p>\n<ul>\n<li><strong>A contact message.</strong> Subject <strong>Data request — delete message</strong>, sent from the same email address you wrote from. The row is removed from the database, and the notification email in the team''s mailbox is deleted with it.</li>\n<li><strong>A review.</strong> Subject <strong>Data request — delete review</strong>, with the page address and the display name on the review. The review is removed from the page and from the stored log. The page''s count is adjusted at the same time.</li>\n<li><strong>A like.</strong> Subject <strong>Data request — reset likes</strong>. Clearing your browser''s site data does this yourself, immediately, and is the faster route. If you want the server-side record cleared too, say so and it will be.</li>\n</ul>\n<p>Deletion is carried out within 30 days and confirmed by reply. Two things cannot be deleted on request because they are not personal data: the daily page counters (a number and a date) and the ordinary server log lines older than the retention window, which no longer exist.</p>\n<h2>Opt out of everything at once</h2>\n<p>If you would rather not interact with any of it: do not press like, do not post a review, and do not send a message. Nothing else on this site stores anything about you. To remove the one cookie, clear site data for this domain in your browser; the site keeps working exactly as before.</p>\n<h2>Object or restrict processing</h2>\n<p>If you are in the EEA or the UK, you can object to processing based on legitimate interests — in practice, the server logs kept for security — and you can ask that a message or review be kept but not published while a question about it is resolved. Write to the same address with the subject <strong>Data request — objection</strong> and say what should stop. Because there is no marketing, there is no marketing opt-out to find: we do not send newsletters, and a contact message never adds you to a list.</p>\n<h2>Do not sell or share</h2>\n<p>We do not sell personal data and we do not share it for cross-context behavioural advertising. There is no "Do Not Sell My Personal Information" link on this site because there is nothing to sell; that is a statement of fact about how the site is built, not a slogan.</p>\n<h2>Complaints</h2>\n<p>If you are not satisfied with how a request was handled, say so through the contact form first — the person who answers can fix most problems, including mistakes made in handling the request itself. If you are in the EEA or the UK you also have the right to complain to your national data-protection authority. We would rather you told us first, but the right exists regardless.</p>\n<h2>Two small practical notes</h2>\n<p><strong>Verification.</strong> A request about a specific contact message is answered to the email address that sent it. That is the only check made, and it is what stops one person from deleting another person''s message.</p>\n<p><strong>Reviews are public by design.</strong> If you post one and later want it gone, it will be removed on request. But until then it is visible to everyone who opens the page, so please do not put an email address, a phone number or anything else private into the text.</p>', 'default', 'published', 'Your data and your choices — access, correction, deletion', 'How to request a copy of your data, correct it, export it or have it deleted from Onim, with the exact route for each request.', '', 0, 0, 1),
  ('terms', 'Terms of use', 'The rules that apply to using the calculators and file tools: what you can rely on, and what you cannot.', '<p>These terms are short because they can be. By using Onim you agree to them. They apply to the calculator pages, the file tools, the blog, the reviews section and the contact form.</p>\n<h2>What this site is</h2>\n<p>Onim is a free library of calculators and browser-based file tools, organised into fifteen sections. Calculators are one of those sections. Nothing here costs money, there is no account to create, and no feature is withheld until you pay, sign up or watch something.</p>\n<h2>The results are a tool, not advice</h2>\n<p>Results are produced by the formulas documented on each page. They are general-purpose: they do not know your tax residency, your lender''s fees, your medical history, your jurisdiction''s building code or the condition of the material in front of you. For decisions with money, health, safety or legal consequences, confirm the result with a qualified professional or with the primary source — the tax office, the lender, the clinician, the code, the manufacturer''s data.</p>\n<p>The <a href="/disclaimer">disclaimer</a> sets out the specific limits for money, health, construction and legal results. It is part of these terms.</p>\n<h2>Files you use in a tool</h2>\n<p>The file tools run in your browser. You are responsible for the file you open and for what you do with the result. Do not use the tools to process material you have no right to process, and do not present converted or compressed output as an original where its authenticity matters — a re-encoded audio file is not a master recording, and a re-saved PDF is not evidence it never was.</p>\n<h2>Accuracy and availability</h2>\n<p>Every calculator is tested against worked examples, and a disagreement between the documented formula and the result is treated as a bug. Even so, we cannot promise the site will never be wrong or never be unavailable. Pages are provided "as is", without warranty of any kind, and results should be checked before they are relied on for anything that matters.</p>\n<p>Where a page is known to be wrong, it is corrected rather than annotated; where a page is out of date because a rule changed — a tax band, a standard, a unit convention — the correction follows. There is no guarantee that a page you read today matches a rule that changed tomorrow.</p>\n<h2>Acceptable use</h2>\n<ul>\n<li>Do not scrape the site at a rate that degrades it for other people, and do not use automated requests to harvest the catalogue.</li>\n<li>Do not use the contact form or the reviews section to send unsolicited advertising, links or repeated messages.</li>\n<li>Do not attempt to reach the administration area, another visitor''s message, or any data that is not yours.</li>\n<li>Do not present the site''s name, logo or layout as your own, or run a copy of this site that misleads people about who is behind it.</li>\n</ul>\n<p>Access is not conditioned on accepting anything beyond these rules. If you break them, access may be limited or blocked without notice — in practice, that means the rate limits on the contact form and on reviews.</p>\n<h2>Content on this site</h2>\n<p>The explanatory text, the worked examples and the interface were written for this site. You may quote a short passage with a link back and a clear attribution. You may not republish whole articles, repackage the catalogue as your own product, or use the text to train a model without permission.</p>\n<p>Formulas, unit definitions and published regulatory thresholds are facts, not property: use them freely. The written explanation of them is ours.</p>\n<h2>Reviews and contributions</h2>\n<p>When you post a review you keep the copyright in what you wrote and you give this site permission to display it on the page it belongs to. Reviews are public. Do not post anything you would not want a stranger to read: no email addresses, no phone numbers, no third parties'' details. Reviews that contain links are refused automatically, and reviews that are abusive, impersonating or off-topic are removed.</p>\n<p>Suggestions you send about how a calculator could be improved can be used to improve it, without obligation or payment. That is not a transfer of anything else you own.</p>\n<h2>Links to other sites</h2>\n<p>Some pages link to sources — a regulator, a standards body, a textbook publisher. Those sites have their own terms and their own accuracy standards. We are not responsible for what they say or do, and a link is not an endorsement of everything on the page it points to.</p>\n<h2>Liability</h2>\n<p>To the extent the law allows, Onim is not liable for indirect or consequential loss arising from use of the site or from reliance on a result, including lost profit, lost data or a decision taken on the strength of a figure that turned out to be wrong. Nothing in these terms excludes liability that cannot lawfully be excluded, including for death or personal injury caused by negligence, or for fraud.</p>\n<h2>Changes to the site and to these terms</h2>\n<p>The site changes: calculators are added, tools are rewritten and pages are retired. These terms may change with it. When they do, the date at the top of the page changes and the change is described in the section it affects. Continuing to use the site after a change means the updated terms apply.</p>\n<h2>Which law applies</h2>\n<p>These terms are governed by the law of the operator''s place of establishment, without prejudice to mandatory consumer protections in your own country of residence. If a dispute cannot be resolved by writing to us first, it belongs in the courts that the law assigns.</p>\n<h2>Contact</h2>\n<p>Questions about these terms, licensing or republication go through the <a href="/contact">contact form</a>. The <a href="/privacy">privacy policy</a>, <a href="/cookies">cookie policy</a> and <a href="/disclaimer">disclaimer</a> are part of the same set and are written to be read together.</p>', 'default', 'published', 'Terms of use — the rules for using Onim''s calculators', 'The terms that apply to using these free calculators and browser file tools: accuracy, acceptable use, content, reviews and liability limits.', '', 0, 0, 1),
  ('disclaimer', 'Disclaimer', 'Money, health, engineering and legal results are estimates — here is exactly where each one stops being reliable.', '<p>Every calculator on this site is an estimate built from a documented formula. This page says, plainly, where the limits are — not to cover the site, but because a result you cannot place in context is a result you should not act on.</p>\n<p>The short version: the arithmetic is right, the world it describes is more complicated than the arithmetic. Each page names its assumptions; this page says why they matter.</p>\n<h2>Money</h2>\n<p>Loan, mortgage, investment, savings and tax calculators reproduce standard formulas. Real statements differ: interest accrues on your lender''s schedule rather than on a neat monthly grid, fees are charged in ways the formula cannot see, rounding happens at a different point, and tax rules change and depend on where you live, how you earn and what else you owe.</p>\n<p>Treat the output as a planning figure. Compare it with an official statement or a lender''s own illustration before committing to anything. Nothing on this site is a quotation, an offer of credit, or investment advice, and no result here takes account of your circumstances in the way a licensed adviser would.</p>\n<h2>Health</h2>\n<p>Health calculators — BMI, body surface area, dosage, pregnancy dates, renal function, risk scores — are educational. They use population-level formulas, not your individual clinical picture. They are not a diagnosis, a prescription, a substitute for a clinician who has examined you, or a reason to change a medication.</p>\n<p>Where a calculator is used in clinical practice, it is designed for use by a trained clinician alongside a full assessment, and even then the guidance is to interpret the number rather than obey it. A "normal" result is not a clean bill of health and an abnormal one is not a diagnosis. If a result worries you, take it to a professional.</p>\n<h2>Biology, chemistry and laboratory results</h2>\n<p>Lab calculators — dilutions, molarity, cell counts, growth rates, protein conversions, gel recipes — depend on the assumptions of the protocol in front of you: the molar mass you are using, the purity of the reagent, the wavelength of your reader, whether a concentration is w/v or v/v. Each page states its own assumptions, and the units are printed next to every field so that a figure copied from a protocol goes in as printed.</p>\n<p>These pages are built for bench work and teaching. They are not a validated quality system, and a result that will be reported as a regulated measurement should be produced by the method your laboratory validated, not by a public web page.</p>\n<h2>Construction, engineering and safety</h2>\n<p>Material, structural, electrical, plumbing and HVAC calculators give estimates from simplified models. Loads, tolerances, soil conditions and codes vary by jurisdiction, by product and by site. Anything that bears weight, conducts current, holds back water or resists fire needs a qualified professional and the manufacturer''s own data.</p>\n<p>If a number will be built into a structure, connected to mains power or used to size a safety system, a calculator on a website is a first estimate at best — never the final word.</p>\n<h2>Legal and regulatory results</h2>\n<p>Date arithmetic, deadline calculators, statutory-interest figures and similar tools reproduce general rules. A deadline that matters — a filing, an appeal, a notice period — depends on your jurisdiction, the court, the agreement and the way the rule is served on you. Confirm it with the court, the authority or a lawyer. Using this site does not create a professional relationship of any kind.</p>\n<h2>Conversions and units</h2>\n<p>Unit conversions are exact where the definition is exact and rounded where the definition is a convention: an inch is exactly 25.4 millimetres, a US gallon is exactly 3.785411784 litres, a calorie has more than one definition and a tonne can be metric or imperial. Pages that involve a conventional unit state which one they use. If a figure must be exact for trade, use the definition your jurisdiction requires.</p>\n<h2>What the results are not</h2>\n<ul>\n<li>They are not personalised: no calculator here knows your full circumstances.</li>\n<li>They are not current in real time: a tax band or a rate changes, and a page is corrected when someone notices.</li>\n<li>They are not a professional opinion, and reading one does not create a professional relationship.</li>\n<li>They are not a guarantee: where a page is found to be wrong, it is fixed — but you should not rely on any figure for anything that cannot be undone.</li>\n</ul>\n<h2>How to check a result yourself</h2>\n<p>Every calculator page prints the formula it used and a worked example with real numbers, so the first check is available on the page. If the worked example and the result disagree, the page is wrong — tell us. Beyond that: compare against a second independent source, sanity-check the order of magnitude, and read the assumptions section before acting on a number that looks surprising.</p>\n<h2>Reporting a problem</h2>\n<p>A wrong result is a bug, not a limitation, and it is treated as one. Send the calculator name, the values you entered and the answer you expected through the <a href="/contact">contact form</a>, and if you know where the correct answer comes from — a textbook, a standard, a statement — say so. Those reports are how this page''s caveats get shorter over time.</p>', 'default', 'published', 'Disclaimer — where a calculator result stops being reliable', 'What the results on this site are and are not: money, health, engineering and legal estimates that need checking against a primary source.', '', 0, 0, 1),
  ('contact', 'Contact', 'A wrong result, a missing calculator, a format the tools do not handle — this is the page for all three.', '<p>Every message on this page is read by a person. There is no ticket robot and no autoresponder; the answer comes from whoever looked into the problem — usually the person who built the page you are writing about.</p>\n<h2>What to include</h2>\n<h3>A wrong result</h3>\n<p>Name the calculator or tool, paste the values you entered, and say what answer you expected. If you know where the expected answer comes from — a textbook, a standard, a spreadsheet, a statement — say so; that turns a report into a fix. A screenshot helps when the problem is visual, but the numbers in text are what get it reproduced.</p>\n<h3>A calculator or a tool that should exist</h3>\n<p>Say what you were trying to work out and what you had in hand. "I have a room''s measurements and I want paint litres by coat" is worth more than "please add a paint calculator". If it is a file format, say which tool you tried and what produced the file.</p>\n<h3>A file the tools will not open</h3>\n<p>Tell us the format, the size, and what produced it. Do not send the file itself unless we ask — the tools run in your browser and we would rather keep it that way. If we need the file to reproduce a bug we will say so, and we will tell you what to strip out of it first.</p>\n<h3>Privacy, advertising, licensing or a legal request</h3>\n<p>All of these reach the same inbox. The <a href="/privacy">privacy policy</a>, <a href="/cookies">cookie policy</a> and <a href="/terms">terms</a> answer the usual questions first; anything about a specific record you sent us is handled through the <a href="/your-data">your data and your choices</a> page. If a copyright holder believes a page reproduces their work, say which page and what is reproduced, and it will be checked and removed if the complaint is right.</p>\n<h3>Accessibility</h3>\n<p>If a page or a tool is hard to use with a keyboard, a screen reader, a large text setting or on a small screen, describe where it breaks. Accessibility problems on a tool site are correctness problems, and they are fixed with the same priority as a wrong number.</p>\n<h2>What happens next</h2>\n<p>Bug reports are answered first, often with the fix rather than a reply — if a page changes, that is the answer arriving. Requests for new calculators are collected and built in batches, and when one you asked for goes live, that is the end of it. Anything about a particular page is answered by someone who has opened that page.</p>\n<p>Messages are stored in the site''s own database and a notification is emailed to the team. If that email fails, the message is not lost: it is kept and picked up from the panel. Messages are deleted once the question is settled, and you can ask for yours to be deleted sooner — see <a href="/your-data">your data and your choices</a>.</p>\n<h2>What we cannot do</h2>\n<ul>\n<li><strong>Give personal advice.</strong> A message that asks "should I take this loan?" gets a pointer to how the calculator''s result should be read, not a recommendation. That is not evasiveness: the site does not know your circumstances, and a few sentences by email would be read as advice.</li>\n<li><strong>Read your file.</strong> The tools never receive it. If something is wrong with a conversion, the format and a description of the problem is what makes it reproducible.</li>\n<li><strong>Recover a result you lost.</strong> Calculator values are never stored, so there is nothing on the server to recover. Re-enter the inputs and the same answer comes back.</li>\n</ul>\n<h2>Response times</h2>\n<p>Most messages are answered within two working days, and bug reports usually within one. There is no guaranteed response time: this is a small team, not a support desk with a service-level agreement. Messages that arrive on a weekend may wait until the start of the week.</p>\n<h2>The form</h2>\n<p>The form below asks for your name, email address, an optional phone number, a subject and your message. Those fields exist to answer you; nothing is added to a mailing list, and no message is ever used for marketing. If you would rather not use the form, the same team reads the address printed in the <a href="/about">About page</a> and on this page''s footer.</p>', 'contact', 'published', 'Contact Onim — bug reports, corrections and requests', 'How to reach the team behind Onim: report a wrong result, ask for a calculator, request a file format, or ask about privacy and advertising.', '', 0, 0, 1),
  ('faq', 'Frequently asked questions', 'How the calculators work, what the file tools do with your files, and what to do when a result looks wrong.', '<p>Answers to the questions that arrive most often — about how the calculators work, how the file tools handle what you give them, and what to do when a result looks wrong. If your question is not here, the <a href="/contact">contact form</a> reaches a person.</p>\n<h2>What is Onim, exactly?</h2>\n<p>A free collection of 4,041 calculators and 19 browser-based file tools, organised into fifteen sections. Calculators are one section. The same catalogue holds the Audio, Video, Image, PDF, Developer, Converter, Security, Gaming, Compressor, Productivity, Design &amp; CSS, Text &amp; Writing, Art &amp; Color and Social &amp; Community tools. Everything is free, and nothing needs an account.</p>\n<h2>Do the calculators store what I type?</h2>\n<p>No. The values you enter are used to compute the result in the page and are gone when you leave or reload. There is no database row for your inputs and nothing is attached to you. The same is true of the copy-link feature: the address bar holds the state so you can share a result, not so the server can keep it.</p>\n<h2>Do the file tools upload my file?</h2>\n<p>No. The tools read the file with the browser''s own file APIs and process it inside the page. There is no upload endpoint for it to reach, which is also why a very large file can be limited by your device''s memory rather than by a server limit. If a tool cannot finish the job without sending the file somewhere, the page says so before you start.</p>\n<h2>Why is one field blank?</h2>\n<p>Many calculators work out whichever value you leave empty. Fill in the ones you know, leave the one you want, and the result appears. A field is never blank because of an error — an error shows a message under the field instead.</p>\n<h2>Why does the result differ from another site?</h2>\n<p>Usually a different assumption rather than a different formula: a different day count in a date calculation, a different rounding step, a calorie that means kilocalorie, a month treated as 30 days rather than a calendar month. Each page states its assumptions. If you can say where the other answer comes from, tell us — sometimes the other site is the one that is wrong, and sometimes the page here needs to offer both conventions.</p>\n<h2>Can I link to a result?</h2>\n<p>Yes. The address bar holds the whole form state, so a copied URL opens the page with the same values and the same answer. Nothing about that link is stored on the server.</p>\n<h2>How accurate is a conversion?</h2>\n<p>Exact where the unit definition is exact — an inch is 25.4 millimetres, a US gallon is 3.785411784 litres — and rounded where the definition is a convention or the value is measured. Pages that involve a conventional unit say which one they use, and results are shown with at most three decimal places.</p>\n<h2>Why does a number field refuse letters?</h2>\n<p>Because a letter in a number field is almost always a mistake that would otherwise produce a silent zero or a wrong answer later. The field says what it expects under the input rather than quietly discarding what you typed.</p>\n<h2>How do I report a wrong answer?</h2>\n<p>Use the <a href="/contact">contact form</a> and include the calculator''s name, the values you entered and the answer you expected. A wrong result is a bug and is fixed rather than annotated. If you know the source of the correct answer, say so.</p>\n<h2>Can I ask for a calculator or a file format?</h2>\n<p>Yes, and a good share of what is on the site today started as one of those messages. Say what you are trying to work out and what you have in hand — that is more useful than a one-line request.</p>\n<h2>Who writes and checks the pages?</h2>\n<p>A small independent team: an editorial lead, an engineering lead and a review lead for the health and science calculators. Some drafting and code review is AI-assisted; every formula, worked example and sign-off is human. The <a href="/about">About page</a> introduces the team, and the <a href="/ai-policy">AI policy</a> states exactly where AI tooling is and is not used.</p>\n<h2>How is the site paid for?</h2>\n<p>By advertising: a small number of clearly marked placements, never inside a result and never between you and an answer. Advertisers never see your inputs or your files. There is no subscription, no premium tier and no account.</p>\n<h2>What data does the site keep?</h2>\n<p>Very little: ordinary server logs for a short period, the messages you deliberately send, the reviews and likes you deliberately post, and a daily page counter that holds no visitor identifier. The <a href="/privacy">privacy policy</a> is the full list, the <a href="/cookies">cookie policy</a> names every cookie, and <a href="/your-data">your data and your choices</a> explains how to have anything removed.</p>\n<h2>Can I use a result at work or in a paper?</h2>\n<p>Yes, with care. Cite the formula the page documents, not the website, and check the result against your own source — a public calculator is not a validated instrument. The <a href="/disclaimer">disclaimer</a> sets out the limits for money, health, construction and legal figures. Quoting a short passage of explanation with a link back is fine; republishing whole articles is not.</p>\n<h2>Something is broken or hard to use — where do I say so?</h2>\n<p>The <a href="/contact">contact form</a>. Accessibility problems count as bugs here, not as feature requests: if a page is hard to use with a keyboard, a screen reader or a small screen, describe where it breaks and it will be fixed with the same priority as a wrong number.</p>', 'faq', 'published', 'Frequently asked questions about Onim tools', 'Answers about units, blank fields, accuracy, file privacy, AI use and how to report a wrong result on this calculator and tools site.', '', 0, 0, 1)
ON DUPLICATE KEY UPDATE
    `title`            = VALUES(`title`),
    `excerpt`          = VALUES(`excerpt`),
    `content`          = VALUES(`content`),
    `template`         = VALUES(`template`),
    `status`           = VALUES(`status`),
    `meta_title`       = VALUES(`meta_title`),
    `meta_description` = VALUES(`meta_description`),
    `show_in_footer`   = VALUES(`show_in_footer`),
    `updated_at`       = NOW();

-- The tagline still described a calculator site. Only the seeded strings are
-- replaced: an owner who wrote their own keeps it.
UPDATE `settings`
   SET `svalue` = 'Free calculators and file tools — the working shown, nothing uploaded'
 WHERE `skey` = 'site_tagline'
   AND `svalue` IN ('4 041 free calculators, each one with its formula spelled out',
                    'Free online calculators for everyday problems',
                    '');

-- A link to a page that does not exist is worse than no link.
DELETE FROM `menu_items` WHERE `url` = '/discover';

/* ---------------------------------------------------------------- footer */

-- The Tool sections column: every section, in header order, so the bottom of
-- every page is a map of the whole site rather than half of it.
INSERT INTO `footer_columns` (`skey`, `title`, `sort_order`, `enabled`, `created_at`)
SELECT 'site-tools', 'Tool sections', 15, 1, NOW()
 WHERE NOT EXISTS (SELECT 1 FROM `footer_columns` WHERE `skey` = 'site-tools');

INSERT INTO `menu_items`
    (`location`, `footer_column_id`, `label`, `url`, `sort_order`, `enabled`, `target`, `created_at`)
SELECT 'footer_column', c.`id`, v.`label`, v.`url`, v.`sort_order`, 1, '_self', NOW()
  FROM (SELECT 'Audio' AS `label`, '/audio' AS `url`, 10 AS `sort_order`
        UNION ALL SELECT 'Video', '/video', 20
        UNION ALL SELECT 'Image', '/image', 30
        UNION ALL SELECT 'PDF', '/pdf', 40
        UNION ALL SELECT 'Developer', '/developer', 50
        UNION ALL SELECT 'Converters', '/converters', 60
        UNION ALL SELECT 'Security', '/security', 70
        UNION ALL SELECT 'Gaming', '/gaming', 80
        UNION ALL SELECT 'Compressors', '/compressors', 90
        UNION ALL SELECT 'Productivity', '/productivity', 100
        UNION ALL SELECT 'Design & CSS', '/design-css', 110
        UNION ALL SELECT 'Text & Writing', '/text-writing', 120
        UNION ALL SELECT 'Art & Color', '/art-color', 130
        UNION ALL SELECT 'Social & Community', '/social-community', 140
        UNION ALL SELECT 'Fun & Random', '/fun-random', 150
        UNION ALL SELECT 'All tools', '/all-tools', 160) AS v
  JOIN `footer_columns` c ON c.`skey` = 'site-tools'
 WHERE NOT EXISTS (
        SELECT 1 FROM `menu_items` m
         WHERE m.`location` = 'footer_column' AND m.`footer_column_id` = c.`id`
           AND m.`url` = v.`url`);

-- The Policies column: six pages a reader may need before trusting a result.
INSERT INTO `footer_columns` (`skey`, `title`, `sort_order`, `enabled`, `created_at`)
SELECT 'site-policies', 'Policies', 40, 1, NOW()
 WHERE NOT EXISTS (SELECT 1 FROM `footer_columns` WHERE `skey` = 'site-policies');

INSERT INTO `menu_items`
    (`location`, `footer_column_id`, `label`, `url`, `sort_order`, `enabled`, `target`, `created_at`)
SELECT 'footer_column', c.`id`, v.`label`, v.`url`, v.`sort_order`, 1, '_self', NOW()
  FROM (SELECT 'Privacy policy' AS `label`, '/privacy' AS `url`, 10 AS `sort_order`
        UNION ALL SELECT 'Cookie policy', '/cookies', 20
        UNION ALL SELECT 'AI policy', '/ai-policy', 30
        UNION ALL SELECT 'Your data and choices', '/your-data', 40
        UNION ALL SELECT 'Terms of use', '/terms', 50
        UNION ALL SELECT 'Disclaimer', '/disclaimer', 60) AS v
  JOIN `footer_columns` c ON c.`skey` = 'site-policies'
 WHERE NOT EXISTS (
        SELECT 1 FROM `menu_items` m
         WHERE m.`location` = 'footer_column' AND m.`footer_column_id` = c.`id`
           AND m.`url` = v.`url`);

-- The Calculators column grows two categories and names the real total.
INSERT INTO `menu_items`
    (`location`, `footer_column_id`, `label`, `url`, `sort_order`, `enabled`, `target`, `created_at`)
SELECT 'footer_column', c.`id`, v.`label`, v.`url`, v.`sort_order`, 1, '_self', NOW()
  FROM (SELECT 'Conversion' AS `label`, '/conversion' AS `url`, 50 AS `sort_order`
        UNION ALL SELECT 'Biology', '/biology', 60) AS v
  JOIN `footer_columns` c ON c.`skey` = 'cat-math'
 WHERE NOT EXISTS (
        SELECT 1 FROM `menu_items` m
         WHERE m.`location` = 'footer_column' AND m.`footer_column_id` = c.`id`
           AND m.`url` = v.`url`);

-- The old Resources column repeated what the three columns above it already
-- link (All calculators, All tools, Search, Blog). It is switched off rather
-- than deleted: the rows stay in the panel, ticked off, if anyone wants them
-- back. templates/partials/footer.php would also suppress the duplicates.
UPDATE `footer_columns` SET `enabled` = 0 WHERE `skey` = 'site-resources';

-- The Company column loses the dead link and gains the pages that replaced it.
INSERT INTO `menu_items`
    (`location`, `footer_column_id`, `label`, `url`, `sort_order`, `enabled`, `target`, `created_at`)
SELECT 'footer_column', c.`id`, v.`label`, v.`url`, v.`sort_order`, 1, '_self', NOW()
  FROM (SELECT 'Blog' AS `label`, '/blog' AS `url`, 30 AS `sort_order`
        UNION ALL SELECT 'Search', '/search', 40
        UNION ALL SELECT 'FAQ', '/faq', 50) AS v
  JOIN `footer_columns` c ON c.`skey` = 'site-company'
 WHERE NOT EXISTS (
        SELECT 1 FROM `menu_items` m
         WHERE m.`location` = 'footer_column' AND m.`footer_column_id` = c.`id`
           AND m.`url` = v.`url`);

-- The bar at the very bottom gains the pages people ask for most often: what
-- the site stores, and whether AI wrote it.
INSERT INTO `menu_items`
    (`location`, `footer_column_id`, `parent_id`, `label`, `url`, `sort_order`, `target`, `enabled`, `created_at`, `updated_at`)
SELECT 'legal', NULL, NULL, 'Cookies', '/cookies', 15, '_self', 1, NOW(), NOW()
 WHERE NOT EXISTS (SELECT 1 FROM `menu_items` WHERE `location` = 'legal' AND `url` = '/cookies');

INSERT INTO `menu_items`
    (`location`, `footer_column_id`, `parent_id`, `label`, `url`, `sort_order`, `target`, `enabled`, `created_at`, `updated_at`)
SELECT 'legal', NULL, NULL, 'AI policy', '/ai-policy', 25, '_self', 1, NOW(), NOW()
 WHERE NOT EXISTS (SELECT 1 FROM `menu_items` WHERE `location` = 'legal' AND `url` = '/ai-policy');

INSERT INTO `menu_items`
    (`location`, `footer_column_id`, `parent_id`, `label`, `url`, `sort_order`, `target`, `enabled`, `created_at`, `updated_at`)
SELECT 'legal', NULL, NULL, 'Your data', '/your-data', 35, '_self', 1, NOW(), NOW()
 WHERE NOT EXISTS (SELECT 1 FROM `menu_items` WHERE `location` = 'legal' AND `url` = '/your-data');
